impl ::flatbuffers::Verifiable for APR<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("REQUEST_ID", Self::VT_REQUEST_ID, false)?
            .visit_field::<i64>("RECEIVED_AT_MS", Self::VT_RECEIVED_AT_MS, false)?
            .visit_field::<aprMethod>("METHOD", Self::VT_METHOD, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("PATH", Self::VT_PATH, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ROUTE", Self::VT_ROUTE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("SCHEMA_NAME", Self::VT_SCHEMA_NAME, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<APRParameter>>>>("PARAMETERS", Self::VT_PARAMETERS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("SELECTION", Self::VT_SELECTION, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("IF_NONE_MATCH", Self::VT_IF_NONE_MATCH, false)?
            .visit_field::<i64>("IF_MODIFIED_SINCE_MS", Self::VT_IF_MODIFIED_SINCE_MS, false)?
            .visit_field::<aprRepresentation>("ACCEPT", Self::VT_ACCEPT, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("CONTENT_TYPE", Self::VT_CONTENT_TYPE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, u8>>>("BODY", Self::VT_BODY, false)?
            .visit_field::<u16>("STATUS", Self::VT_STATUS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ERROR_CODE", Self::VT_ERROR_CODE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ERROR_MESSAGE", Self::VT_ERROR_MESSAGE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("CALLER_ID", Self::VT_CALLER_ID, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<APRParameter>>>>("RESPONSE_HEADERS", Self::VT_RESPONSE_HEADERS, false)?
            .finish();
        Ok(())
    }
}

